import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # 1. Apply-once semantics: distinct by seq (keep first occurrence of a seq).
    events = cdc_events.drop_duplicates(subset="seq", keep="first")

    # Build initial current state from target_state.
    current_state = {}
    existed_ever = {}
    orig_last_seq = {}
    for _, row in target_state.iterrows():
        oid = int(row["order_id"])
        current_state[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": int(row["last_seq"]),
        }
        existed_ever[oid] = True
        orig_last_seq[oid] = int(row["last_seq"])

    tomb_rows = []

    # Process events per order, in seq order, with the replay guard applied.
    for oid, grp in events.groupby("order_id"):
        grp_sorted = grp.sort_values("seq")

        if oid in orig_last_seq:
            guard = orig_last_seq[oid]
            grp_sorted = grp_sorted[grp_sorted["seq"] > guard]

        if grp_sorted.empty:
            continue

        last_op = None
        last_seq_val = None

        for _, ev in grp_sorted.iterrows():
            op = ev["op"]
            seq = int(ev["seq"])

            if op in ("I", "U"):
                if oid in current_state:
                    status = ev["status"]
                    if op == "U" and pd.isna(ev["amount"]):
                        amount = current_state[oid]["amount"]
                    else:
                        amount = ev["amount"]
                    current_state[oid] = {
                        "status": status,
                        "amount": amount,
                        "last_seq": seq,
                    }
                else:
                    current_state[oid] = {
                        "status": ev["status"],
                        "amount": ev["amount"],
                        "last_seq": seq,
                    }
                existed_ever[oid] = True
            elif op == "D":
                if oid in current_state:
                    del current_state[oid]
                # D on a missing order does nothing; existed_ever unchanged.

            last_op = op
            last_seq_val = seq

        if existed_ever.get(oid, False) and last_op == "D":
            tomb_rows.append({"order_id": oid, "deleted_seq": last_seq_val})

    new_state_rows = []
    for oid, st in current_state.items():
        new_state_rows.append(
            {
                "order_id": oid,
                "status": st["status"],
                "amount": st["amount"],
                "last_seq": st["last_seq"],
            }
        )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])

    if not new_state.empty:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
    else:
        new_state = new_state.astype(
            {
                "order_id": "int64",
                "status": "object",
                "amount": "float64",
                "last_seq": "int64",
            }
        )

    if not tombstones.empty:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = tombstones.astype({"order_id": "int64", "deleted_seq": "int64"})

    return {"new_state": new_state, "tombstones": tombstones}
